  solid(-16, H / 2, -10, T, H, 20, mat.wallDark); // z -20..0
  // East corridor mirror.
  solid(16, H / 2, -10, T, H, 20, mat.wallDark);

  // ---- Cover: crates, containers, barrels, pillars ------------------------
  const crate = (x, z, s, m = mat.crate) => solid(x, s / 2, z, s, s, s, m);
