  function pipeRun(px, py, pz, len, r, r2) {
    const amt = Math.max(1, Math.round(len / 5));
    for (let i = 0; i < amt; i += 1) {
      plate(px, py, pz - len / 2 + 5 * i + 2.5, r2, r, 4.6, mat.pipe);
