      -0.06 + bobX * 0.5 + switchSwing * 0.6,
      kick * 1.2
    );

    view.flash.visible = state.flashT > 0;
    view.flashLight.intensity = state.flashT > 0 ? 6 * state.flashT : 0;
  }

  return {
    state,
    WEAPONS,
    selectSlot,
    buyPrimary,
    buyNade,
    resetForRound,
    step,
    tryFire,
    tryReload,
    tryThrow,
    firemode,
    spreadFor,
    currentDef,
  };
